<script>
 import RegionState from './RegionState.svelte';
 import {onMount} from 'svelte';import {studio} from '../studio.svelte';import {navigate} from '../app/shell.svelte';import {getSettingsApi} from '../services/settings.ts';import TeamAdmin from './TeamAdmin.svelte';import WorkspaceSettings from './WorkspaceSettings.svelte';
 const api=getSettingsApi(),groups=[['keys','API 密钥'],['models','模型选择'],['accounts','账号与配额'],['limits','费用与确认门槛'],['certificate','证书']];
 let group=$state('keys'),status=$state('loading'),error=$state(''),config=$state(null),credentials=$state({google:false,deepseek:false,poe:false}),editing=$state({}),keyValues=$state({}),feedback=$state({}),accounts=$state([]),cert=$state(null),certError=$state(''),pending=$state({});let chain=Promise.resolve(),alive=true;
 const providers=[['google','Google'],['deepseek','DeepSeek'],['poe','Poe']];
 async function load(){status='loading';error='';try{const [settings,keys]=await Promise.all([api.read(),api.credentials()]);if(!alive)return;config=settings;credentials=keys;status='ready';}catch(e){error=e.message;status='error';}void api.accounts().then(value=>{if(alive)accounts=value.accounts;}).catch(e=>feedback.accounts=e.message);void api.certificate().then(value=>{if(alive)cert=value;}).catch(e=>certError=e.message);}
 onMount(()=>{if(!window.__gvpakLocalHost){navigate('/',{replace:true});return;}void load();return()=>alive=false;});
 function saved(field,text){feedback={...feedback,[field]:text};}
 async function patch(field,value){pending={...pending,[field]:true};saved(field,'保存中…');chain=chain.catch(()=>{}).then(()=>api.patch({[field]:value}));try{const result=await chain;if(!alive)return;config={...config,...result};saved(field,'已保存');window.dispatchEvent(new Event('execution-preferences'));}catch(e){saved(field,'保存失败：'+e.message);}finally{if(alive)pending={...pending,[field]:false};}}
 function number(field,event){const input=event.currentTarget;if(!input.validity.valid||input.value===''){saved(field,'请输入有效数值');return;}void patch(field,Number(input.value));}
 async function key(provider,event){const value=event.currentTarget.value.trim();if(!value||pending[provider])return;pending={...pending,[provider]:true};saved(provider,'保存中…');try{await api.setCredential(provider,value);keyValues={...keyValues,[provider]:''};credentials={...credentials,[provider]:true};editing={...editing,[provider]:false};saved(provider,'已保存');}catch(e){saved(provider,'保存失败：'+e.message);}finally{pending={...pending,[provider]:false};}}
 async function quota(id,event){const input=event.currentTarget;if(!input.validity.valid)return;await patch('quotas',{[id]:input.value===''?null:Number(input.value)});}
 async function regenerate(){pending.certificate=true;certError='';saved('certificate','正在重新生成…');try{cert=await api.regenerate();saved('certificate','已保存；请为同事重新安装证书。');}catch(e){certError=e.message;}finally{pending.certificate=false;}}
 async function download(){try{const result=await api.installer(),url=URL.createObjectURL(new Blob([result.content],{type:'application/octet-stream'})),link=document.createElement('a');link.href=url;link.download=result.name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);saved('certificate','安装脚本已下载');}catch(e){certError=e.message;}}
 async function copyFingerprint(){try{await navigator.clipboard.writeText(cert.fingerprint);saved('certificate','指纹已复制');}catch{certError='复制失败，请选中指纹后按 Ctrl+C。';}}
</script>
<div class="settings-page" aria-label="应用设置"><header><h1>设置</h1>{#if api.mode==='mock'}<span>模拟模式</span>{/if}</header><div class="settings-layout"><nav aria-label="设置分组">{#each groups as [id,label]}<button aria-current={group===id?'page':undefined} class:active={group===id} onclick={()=>group=id}>{label}</button>{/each}</nav><main aria-label="设置表单">
 {#if status==='loading'}<RegionState compact state="loading" title="正在读取设置"/>{:else if status==='error'}<RegionState compact state="error" title="无法读取设置" message={error} onretry={load}/>{:else if config}
 {#if group==='keys'}<section><h2>API 密钥</h2><p class="description">密钥只写入主机凭据管理器。输入完成并离开字段后自动保存。</p>{#each providers as [provider,label]}<div class="setting-field"><div class="setting-title"><label for={'key-'+provider}>{label}</label><span>{credentials[provider]?'已设置 ••••':'未设置'}</span>{#if credentials[provider]&&!editing[provider]}<button class="line-button" onclick={()=>{editing={...editing,[provider]:true};keyValues={...keyValues,[provider]:''};}}>替换</button>{/if}</div>{#if !credentials[provider]||editing[provider]}<input id={'key-'+provider} aria-label={label+' API 密钥'} type="password" autocomplete="new-password" placeholder="输入新密钥" bind:value={keyValues[provider]} disabled={pending[provider]} onblur={event=>key(provider,event)}/>{/if}<small role="status">{feedback[provider]||''}</small></div>{/each}</section>
 {:else if group==='models'}<section><h2>模型选择</h2><label class="setting-field">常规生图默认模型<select aria-label="常规生图默认模型" value={config.imageModel} disabled={pending.imageModel} onchange={event=>patch('imageModel',event.currentTarget.value)}>{#each studio.catalog?.models||[] as model}<option value={model.id}>{model.name}</option>{/each}</select><small role="status">{feedback.imageModel||''}</small></label><label class="setting-field">新品图像识别<select aria-label="新品图像识别模型" disabled><option>Gemini 3.8 Flash</option></select></label><label class="setting-field">新品套图与对话场景生成<select aria-label="新品套图模型" disabled><option>Nano Banana 2.1</option></select></label><label class="setting-field">对话任务规划<select aria-label="对话规划模型" disabled><option>DeepSeek Flash</option></select></label><p class="description">新品模式沿用已验证的识别与多参考图模型；常规生图可单独选择模型。</p></section><details class="workspace-details"><summary>工作区与显示</summary><WorkspaceSettings/></details>
 {:else if group==='accounts'}<section><h2>账号与配额</h2><p class="description">配额按累计已完成的任务输出张数统计，不代表供应商余额。留空表示不设上限；达到门槛时仍可在对话中确认继续。</p>{#each [{id:'host',username:'主机'},...accounts] as account}<label class="quota-field"><span>{account.username}<small>{config.usage?.[account.id]??'—'} 张已用</small></span><input aria-label={account.username+' 配额上限'} type="number" min="1" max="10000000" step="1" placeholder="不设上限" value={config.quotas[account.id]??''} disabled={pending.quotas} onchange={event=>quota(account.id,event)}/><span>张</span></label>{/each}<small role="status">{feedback.quotas||feedback.accounts||''}</small></section><TeamAdmin onchanged={()=>api.accounts().then(value=>accounts=value.accounts)}/>
 {:else if group==='limits'}<section><h2>费用与确认门槛</h2><p class="description">更改后自动保存，后续任务使用新的门槛。确认仍显示在对话内。</p>{#each [['analysisCount','看图描述超过（张）',1,5000,1],['generationCount','单次生成超过（张）',1,5000,1],['costCny','生图预估费用超过（元）',0.01,1000000,0.01],['filterCount','大批筛选提示超过（张）',1,5000,1]] as [field,label,min,max,step]}<label class="setting-field">{label}<input aria-label={label} type="number" {min} {max} {step} value={config[field]} disabled={pending[field]} onchange={event=>number(field,event)}/><small role="status">{feedback[field]||''}</small></label>{/each}<p class="description">筛选数量只提示处理范围；可撤销的本地操作直接执行。</p></section>
 {:else if group==='certificate'}<section><h2>证书</h2><p class="description">用于同事通过 HTTPS 连接本机。重新生成后，同事需要安装新的证书；已有账号和素材保留。</p>{#if cert?.fingerprint}<label class="setting-field">SHA-256 指纹<textarea readonly aria-label="证书 SHA-256 指纹" value={cert.fingerprint}></textarea></label><button class="line-button" onclick={copyFingerprint}>复制指纹</button>{/if}<div class="certificate-actions"><button class="line-button" disabled={pending.certificate} onclick={regenerate}>重新生成</button><button class="primary" disabled={!cert?.fingerprint||pending.certificate} onclick={download}>下载 安装证书.cmd</button></div><small role="status">{feedback.certificate||''}</small>{#if certError}<p role="alert">{certError}</p>{/if}</section>{/if}
 {/if}</main></div></div>
<style>.settings-page{height:100%;min-height:0;display:flex;flex-direction:column;background:var(--bg);color:var(--text);color-scheme:light dark}.settings-page>header{display:flex;align-items:center;gap:20px;padding:24px 32px 20px;border-bottom:1px solid var(--border)}h1{font-size:24px}h2{font-size:18px;margin:0 0 16px}.settings-layout{display:grid;grid-template-columns:200px minmax(0,1fr);flex:1;min-height:0}.settings-layout>nav{padding:20px 12px;border-right:1px solid var(--border);display:flex;flex-direction:column;gap:4px}.settings-layout>nav button{justify-content:flex-start;padding:12px 16px;font-size:13px}.settings-layout>nav button.active{color:var(--accent);background:var(--accent-soft)}.settings-layout>main{overflow:auto;padding:28px 36px;min-width:0}.settings-layout section{max-width:760px;margin-bottom:24px}.description{font-size:13px;line-height:1.7;color:var(--text-dim);margin:0 0 24px}.setting-field{display:flex;flex-direction:column;gap:8px;margin:20px 0;font-size:13px;max-width:600px}.setting-title{display:flex;align-items:center;gap:16px}.setting-title>span{color:var(--text-dim);margin-left:auto}.setting-field small{min-height:16px;color:var(--text-dim)}.setting-field input,.setting-field select{min-height:38px;width:100%}.setting-field textarea{resize:none;min-height:80px;word-break:break-all}.quota-field{display:flex;align-items:center;gap:16px;margin:18px 0;font-size:13px}.quota-field>span:first-child{min-width:130px}.quota-field input{width:180px}.quota-field small{display:block;margin-top:6px;font-size:12px;color:var(--text-dim)}.certificate-actions{display:flex;gap:12px;flex-wrap:wrap;margin:20px 0}.workspace-details{max-width:760px;border-top:1px solid var(--border);padding:18px 0}.workspace-details summary{cursor:pointer;font-size:13px}.workspace-details :global(.settings-block){margin-top:20px}.settings-layout [role=alert]{color:var(--danger);line-height:1.7}.settings-page :global(input:not([type=range]):not([type=checkbox])),.settings-page :global(select),.settings-page :global(textarea){background:var(--bg-elev);color:var(--text);border-color:var(--border)}.settings-page :global(.settings-block){color:var(--text);background:var(--bg-elev);border-color:var(--border)}.settings-page :global(.line-button){border-color:var(--border);color:var(--text)}.settings-page :global(button:hover){background:var(--bg-sunken)}.settings-page :global(.primary){background:var(--accent);color:var(--on-accent)}.settings-page :global(.primary:hover){background:var(--accent)}.settings-layout>nav button.active{color:var(--accent);background:var(--accent-soft)}.settings-page :global(h3){color:var(--text-dim)}@media(prefers-reduced-motion:reduce){.settings-page :global(*){transition:none!important}}</style>
